package computer.parachute.app

// Hand-written (not generated by `tauri android init`). An applet's saved file (src-tauri/src/files.rs `save_file`):
// Rust writes the bytes to the app's cache (cache/save/), and saveToDownloads copies them into the public Downloads
// collection through MediaStore (Android 10+, no storage permission) and says the name it got there. Ported from the
// Uni app's FilesPlugin. Only the shell's Rust side calls it: no JavaScript-facing permission.

import android.app.Activity
import android.content.ContentValues
import android.os.Build
import android.os.Environment
import android.provider.MediaStore
import android.webkit.MimeTypeMap
import androidx.annotation.RequiresApi
import app.tauri.annotation.Command
import app.tauri.annotation.InvokeArg
import app.tauri.annotation.TauriPlugin
import app.tauri.plugin.Invoke
import app.tauri.plugin.JSObject
import app.tauri.plugin.Plugin
import java.io.File

@InvokeArg
class SaveToDownloadsArgs {
  lateinit var path: String
  lateinit var name: String
  var mime: String? = null
}

@TauriPlugin
class FilesPlugin(private val activity: Activity) : Plugin(activity) {
  /** The type other apps go by: from the extension first (it must agree with the name), else the one given. */
  private fun mimeFor(name: String, hint: String?): String {
    val ext = name.substringAfterLast('.', "").lowercase()
    return MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext)
      ?: hint?.takeIf { it.matches(Regex("^[a-z0-9.+-]+/[a-z0-9.+-]+$")) }
      ?: "application/octet-stream"
  }

  /** `report.pdf` → `report (2).pdf`, as the desktop numbers it (src-tauri/src/files.rs). */
  private fun numbered(name: String, n: Int): String {
    val dot = name.lastIndexOf('.')
    return if (dot > 0) "${name.substring(0, dot)} ($n)${name.substring(dot)}" else "$name ($n)"
  }

  /** Only a file directly in cache/save/, the folder files.rs writes to. */
  private fun savedFile(path: String): File? {
    val dir = File(activity.cacheDir, "save").canonicalFile
    val file = File(path).canonicalFile
    return file.takeIf { it.parentFile == dir && it.isFile }
  }

  /** A plain file name: no folder part, not hidden, not empty. */
  private fun safeName(name: String): Boolean =
    name.isNotBlank() && !name.contains('/') && !name.contains('\\') && !name.startsWith('.')

  @Command
  fun saveToDownloads(invoke: Invoke) {
    val args = try { invoke.parseArgs(SaveToDownloadsArgs::class.java) } catch (e: Exception) {
      invoke.reject("bad save request"); return
    }
    if (Build.VERSION.SDK_INT < 29) {
      invoke.reject("Saving to Downloads needs Android 10 or newer")
      return
    }
    if (!safeName(args.name)) {
      invoke.reject("bad file name"); return
    }
    val src = savedFile(args.path)
    if (src == null) {
      invoke.reject("the file to save is missing; try again")
      return
    }
    // Up to 25 MB: not on the caller's thread.
    Thread { publish(invoke, args.name, args.mime) { out -> src.inputStream().use { it.copyTo(out, 1 shl 16) } } }.start()
  }

  /** Write a new Downloads entry called `name` with `write`, publish it, and resolve with the name it really got. */
  @RequiresApi(29)
  private fun publish(invoke: Invoke, name: String, mime: String?, write: (java.io.OutputStream) -> Unit) {
    val resolver = activity.contentResolver
    val values = ContentValues().apply {
      put(MediaStore.MediaColumns.DISPLAY_NAME, name)
      put(MediaStore.MediaColumns.MIME_TYPE, mimeFor(name, mime))
      put(MediaStore.MediaColumns.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS)
      put(MediaStore.MediaColumns.IS_PENDING, 1)
    }
    var uri: android.net.Uri? = null
    try {
      uri = resolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values)
        ?: throw IllegalStateException("Downloads refused the file")
      resolver.openOutputStream(uri)?.use(write)
        ?: throw IllegalStateException("could not write to Downloads")
      // Publishing moves the file to its name. MediaStore can refuse that name (UNIQUE files._data) when a row
      // for it outlived its file; then publish as "name (2).ext", … without copying again. A refusal can be an
      // exception or no row updated; until one publish takes, the file stays pending (hidden), so never say saved.
      for (n in 0..20) {
        val done = ContentValues().apply {
          put(MediaStore.MediaColumns.IS_PENDING, 0)
          if (n > 0) put(MediaStore.MediaColumns.DISPLAY_NAME, numbered(name, n + 1))
        }
        val published = try { resolver.update(uri, done, null, null) > 0 } catch (e: Exception) {
          if (n == 20) throw e else false
        }
        if (published) break
        if (n == 20) throw IllegalStateException("Downloads did not take the file")
      }
      // MediaStore renames a duplicate itself ("report (1).pdf"): report the name it really has.
      var saved = name
      resolver.query(uri, arrayOf(MediaStore.MediaColumns.DISPLAY_NAME), null, null, null)?.use { c ->
        if (c.moveToFirst()) c.getString(0)?.let { saved = it }
      }
      val out = JSObject()
      out.put("name", saved)
      invoke.resolve(out)
    } catch (e: Exception) {
      uri?.let { runCatching { resolver.delete(it, null, null) } }
      invoke.reject("Couldn't save to Downloads: ${e.message ?: e.javaClass.simpleName}")
    }
  }
}
